import type {PieceType,Equipment} from './types';
export type Rarity='base'|'common'|'rare'|'epic'|'legendary';
export type Item={id:string;style:string;rarity:Rarity;name:string}&({kind:'piece';type:PieceType}|{kind:'board'});
export type Style={id:string;name:string;rarity:Rarity;accent:string;light:string;dark:string};
export const TYPES:PieceType[];
export const PIECE_NAMES:Record<PieceType,string>;
export const STYLES:Style[];
export const ITEMS:Item[];
export const rarityNames:Record<Rarity,string>;
export const itemById:(id:string|undefined)=>Item|undefined;
export const styleById:(id:string|undefined)=>Style;
export const pieceId:(style:string,type:string)=>string;
export const boardId:(style:string)=>string;
export const craftCost:(item:Item)=>number;
export const duplicateRefund:(item:Item)=>number;
export const defaultEquipment:()=>Equipment;
export const baseInventory:()=>string[];
export const COSTS:Record<Exclude<Rarity,'base'>,number>;
export const REFUNDS:Record<Exclude<Rarity,'base'>,number>;
export const CHEST_COST:number;
export const EMPTY_SHARDS:number;
